//create the SQL expression to map a feature to its inspections:

var rtbl = FeatureSetByRelationshipName($feature,"FQ_DataCollection_Records2")
var code = $feature.GlobalID
var name = $feature.APP_NAME

//the related records are created on GlobalID/GUID

var sql = "GUID = '" + code + "'";
console(name)
console(sql)
var inspections = Filter(rtbl,sql);
var total_inspections = Count(inspections)
console(total_inspections)
var last_inspection_date = ""
if (total_inspections > 0) {
    var ordered_inspections = OrderBy(inspections, 'Date')
    var latest_inspection = first(ordered_inspections)
    var latest_date = Text(latest_inspection.Date, 'M/DD/YY')
    last_inspection_date = latest_date
}
else {
    last_inspection_date = "has not been inspected yet"
}

return last_inspection_date
